List<Tea> parseBookSeed() {
  final result = <Tea>[];
  for (final line in bookSeed.split('\n')) {
    final row = line.trim();
    if (row.isEmpty) continue;
    final cells = row.split('|');
    if (cells.length < 13) continue;
    String at(int i) => i < cells.length ? cells[i] : '';
    final steeps = at(9)
        .split(',')
        .map((e) => int.tryParse(e.trim()) ?? 0)
        .where((e) => e > 0)
        .toList();
    result.add(
      Tea(
        id: at(0),
        name: at(1),
        category: at(2),
        origin: at(3),
        flavor: at(4),
        aroma: at(5),
        brewTemp: int.tryParse(at(6)) ?? 90,
        ratio: at(7),
        vessel: at(8),
        steeps: steeps.isEmpty ? <int>[20, 25, 30] : steeps,
        summary: at(10),
        story: at(11),
        source: at(12),
        image: at(13).isEmpty ? null : at(13),
        appearance: at(14),
        liquor: at(15),
        taste: at(16),
        leaf: at(17),
        brewNote: at(18),
        tasteNote: at(19),
        group: at(20),
        originDetail: at(21),
      ),
    );
  }
  return result;
}
